import re

def solve(env, goal):
    # Parse goal for target object and destination receptacle
    goal_lower = goal.lower()

    # Determine target object type from goal
    target = None
    for word in goal_lower.split():
        if word not in ("a", "an", "the", "some", "clean", "and", "put", "it", "in", "to", "on", "into", "with"):
            if target is None:
                target = word
                break

    # More robust: extract object before "and put" or "in/to/on"
    m = re.search(r'clean (?:some|a|an|the)?\s*(\w+?)(?:\s+and\s+put|\s+in|\s+to|\s+on|\s+into)', goal_lower)
    if m:
        target = m.group(1)
    else:
        m2 = re.search(r'(?:put|place|move)\s+(?:some|a|an|the)?\s*(\w+?)\s+(?:in|to|on|into)', goal_lower)
        if m2:
            target = m2.group(1)

    # Determine destination receptacle
    dest = None
    m3 = re.search(r'(?:in|to|on|into)\s+(?:the\s+)?(\w+(?:\s+\d+)?)', goal_lower)
    if m3:
        candidate = m3.group(1)
        # If candidate matches target, try next preposition
        if candidate != target:
            dest = candidate
    if dest is None:
        # try find after "put it in"
        m4 = re.search(r'(?:put|place|move)\s+it\s+(?:in|to|on|into)\s+(?:the\s+)?(\w+(?:\s+\d+)?)', goal_lower)
        if m4:
            dest = m4.group(1)

    if dest is None:
        # fallback: last preposition phrase
        parts = re.split(r'\b(in|to|on|into)\b', goal_lower)
        if len(parts) >= 3:
            dest = parts[-1].strip().split()[0] if parts[-1].strip() else None

    if dest is None:
        dest = "shelf 1"

    # Normalize: remove leading article
    def norm(s):
        if not s:
            return s
        s = re.sub(r'^(a|an|the)\s+', '', s.strip())
        return s

    target = norm(target)
    dest = norm(dest)

    # If target or dest is generic like "plate", "shelf", we need to find an actual instance
    # Track state
    current_loc = None
    holding = None
    cleaned = False
    opened = set()
    visited = set()
    cleaned_objects = set()

    # Extract room receptacles from first observation
    obs = env.observation
    room_objs = re.findall(r'\b([a-z]+(?:\s+\d+)?)\b(?=\s*[,.]|\s+and)', obs.lower())
    # Better: find all "name number" patterns
    room_receptacles = re.findall(r'\b([a-z]+ \d+)\b', obs.lower())
    room_receptacles = list(dict.fromkeys(room_receptacles))

    # Parse what we know about objects in each receptacle
    knowledge = {}  # receptacle -> list of object names

    def update_knowledge(text):
        # "On the X, you see a, b, and c."
        m = re.search(r'(?:On|In) the ([a-z]+ \d+), you (?:see|find) ([^.]+)', text.lower())
        if m:
            rec = m.group(1)
            items_str = m.group(2)
            items = re.findall(r'\b([a-z]+ \d+)\b', items_str)
            knowledge[rec] = items
        m2 = re.search(r'In it, you see ([^.]+)', text.lower())
        if m2 and current_loc:
            items = re.findall(r'\b([a-z]+ \d+)\b', m2.group(1))
            knowledge[current_loc] = items
        # "you see nothing"
        if 'you see nothing' in text.lower():
            if current_loc:
                knowledge[current_loc] = []

    def matches_target(obj):
        return obj == target or (target and obj.startswith(target + ' '))

    def matches_dest(rec):
        return rec == dest or (dest and rec.startswith(dest + ' '))

    def find_target():
        # search knowledge for target object
        for rec, items in knowledge.items():
            for item in items:
                if matches_target(item) and item not in cleaned_objects:
                    return rec, item
        return None, None

    def find_dest():
        # choose a receptacle matching dest
        for rec in room_receptacles:
            if matches_dest(rec):
                return rec
        if room_receptacles:
            for rec in room_receptacles:
                if dest and rec.startswith(dest.split()[0]):
                    return rec
        return None

    def go(loc):
        nonlocal current_loc
        r = env.step(f"go to {loc}")
        update_knowledge(r)
        if r.startswith("You arrive"):
            current_loc = loc
            visited.add(loc)
            return True
        return False

    def open_rec(rec):
        if rec in opened:
            return True
        r = env.step(f"open {rec}")
        update_knowledge(r)
        if "open" in r.lower() and "closed" not in r.lower()[:20]:
            opened.add(rec)
            return True
        return False

    # Phase 1: explore to find target object
    # First, check if any known receptacle has it
    found_rec, found_obj = find_target()

    # Explore receptacles in batches; prioritize those likely to contain target
    # Also check containers (fridge, microwave) by opening
    if found_obj is None:
        # visit receptacles
        candidates = list(room_receptacles)
        # containers need opening
        containers = [r for r in candidates if any(c in r for c in ('fridge','microwave','cabinet','drawer'))]
        others = [r for r in candidates if r not in containers]

        for rec in containers + others:
            if found_obj is not None:
                break
            go(rec)
            if rec in containers or rec.startswith(('cabinet','drawer')):
                open_rec(rec)
            # after arriving/opening, knowledge may be updated
            found_rec, found_obj = find_target()

    # If still not found, maybe target is a generic like "plate" and we need to try more
    if found_obj is None:
        # try all receptacles again with look
        for rec in room_receptacles:
            if found_obj is not None:
                break
            go(rec)
            if rec.startswith(('cabinet','drawer','fridge','microwave')):
                open_rec(rec)
            r = env.step("look")
            update_knowledge(r)
            found_rec, found_obj = find_target()

    if found_obj is None:
        # give up gracefully
        return

    # Phase 2: take the object
    if current_loc != found_rec:
        go(found_rec)
        if found_rec.startswith(('cabinet','drawer','fridge','microwave')):
            open_rec(found_rec)
    r = env.step(f"take {found_obj} from {found_rec}")
    if "You pick up" in r or "pick up" in r.lower():
        holding = found_obj

    # Phase 3: clean it
    if holding:
        # find sinkbasin
        sink = None
        for rec in room_receptacles:
            if rec.startswith('sinkbasin'):
                sink = rec
                break
        if sink is None:
            sink = 'sinkbasin 1'
        go(sink)
        r = env.step(f"clean {holding} with {sink}")
        if "clean" in r.lower():
            cleaned = True
            cleaned_objects.add(holding)

    # Phase 4: move to destination
    if holding:
        d = find_dest()
        if d is None:
            d = dest
        if d and d != dest:
            # try direct
            pass
        go(d)
        r = env.step(f"move {holding} to {d}")
        if "move" in r.lower():
            holding = None
